            var score2 = this._scoreAnswer(d.estimate2, round.correct2, round.tol2);
            var periodScore = score1 + score2;

            state.domainState.totalScore += periodScore;
            state.domainState.problemsSolved += 1;
            if (periodScore > state.domainState.bestScore) {
                state.domainState.bestScore = periodScore;
            }
            state.domainState.scoreHistory.push(periodScore);
